//! Generated data tables and enums for the jackdaw engine.
//!
//! The tables (centers, blinds, tags, stakes, seals, challenges, poker hands, blind amounts) are
//! generated by `cargo xtask codegen` from `jackdaw/engine/data/*.json` plus the challenge and
//! hand extracts, and the output is checked in; CI runs `cargo xtask codegen --check` to keep it in
//! sync. Like `jackdaw-core`, this crate has no PyO3 dependency and no global mutable state.
//!
//! Not generated yet: this is the Phase 0 stub.
#![forbid(unsafe_code)]

/// The Balatro release the tables are extracted from (`version.jkr` of the game source).
pub const BALATRO_VERSION: &str = "1.0.1o-FULL";

#[cfg(test)]
mod tests {
    use super::BALATRO_VERSION;

    #[test]
    fn targets_balatro_1_0_1o() {
        assert!(BALATRO_VERSION.starts_with("1.0.1o"));
    }
}
